import struct, zlib
w,h=48,16
def px(r,g,b): return bytes([r,g,b])
rows = []
for y in range(h):
    row=b"\x00"
    for x in range(w):
        if x<16: row+=px(0,0,255)
        elif x<32: row+=px(0,255,0)
        else: row+=px(255,0,0)
    rows.append(row)
data=b"".join(rows)
def chunk(tag,payload):
    return struct.pack(">I",len(payload))+tag+payload+struct.pack(">I",zlib.crc32(tag+payload)&0xFFFFFFFF)
header=b"\x89PNG\r\n\x1a\n"
ihdr=struct.pack(">IIBBBBB",w,h,8,2,0,0,0)
png=header+chunk(b"IHDR",ihdr)+chunk(b"IDAT",zlib.compress(data))+chunk(b"IEND",b"")
open("tex.png","wb").write(png)
print("wrote png")
EOF
